 n,R,C=int(m[1]),int(m[2]),int(m[3]); parse=lambda t:[list(map(int,re.findall(r"\d+",z))) for z in t.splitlines()];g,o=parse(m[4]),parse(m[5]); assert all(len(x)==C for x in g+o)
 H=[r for r in range(R) if g[r][0]==g[r][-1]==1]; V=[x for x in range(C) if g[0][x]==g[-1][x]==1]
 labels={};comps=[]
 for y in range(R):
  for x in range(C):
   if g[y][x]!=2 or (y,x) in labels:continue
   k=len(comps);q=[(y,x)];labels[(y,x)]=k;a=[]
   while q:
    yy,xx=q.pop();a.append((yy,xx))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     t=(yy+dy,xx+dx)
