    for dy,dx in ((0,-1),(0,1)):ray(h,v,dy,dx,src)
  else:
   for srcx in (C//2,):
    src=labels.get((h,srcx));
    if src is not None:predicted.add(src)
    ray(h,srcx,0,-1,src);ray(h,srcx,0,1,src)
 for v in V:
  if H: continue
  srcy=(R-1)/2
  for direction in (-1,1):
   y=int(srcy) if direction==-1 else int(srcy)+1
   xx=v
   while 0<=y<R:
    k=labels.get((y,xx))
    if k is not None:predicted.add(k);break
    y+=direction
 fmt=lambda S:[(min(y for y,x in comps[k]),max(y for y,x in comps[k]),min(x for y,x in comps[k]),max(x for y,x in comps[k])) for k in sorted(S)]
