import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/H0-hermes-luna6-high-rnd0/frozen/held-out/play/users/u027/system/state/hermes/state.db'
c=sqlite3.connect(p); sid='98ffa208-9de8-4968-bcb1-439b26ba8073'
for mid in [5,19,37]:
 text=c.execute('SELECT content FROM messages WHERE id=?',(mid,)).fetchone()[0]
 m=re.search(r'Demo pair \d+ input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \d+ output \(\d+x\d+\):\n(.*?)\n\nSame instance',text,re.S)
 assert m,mid
 h,w=map(int,m.group(1,2)); a=[list(map(int,r.split())) for r in m.group(3).splitlines()]; expected=[list(map(int,r.split())) for r in m.group(4).splitlines()]
 assert len(a)==h and all(len(r)==w for r in a)
 ones=[(r,x) for r in range(h) for x in range(w) if a[r][x]==1]
 rows=sorted({r for r,x in ones if sum(1 for rr,xx in ones if rr==r)>=2})
 cols=sorted({x for r,x in ones if sum(1 for rr,xx in ones if xx==x)>=2})
 out=[r[:] for r in a]; seen=set(); changed=0
 for r in range(h):
  for x in range(w):
   if a[r][x]!=2 or (r,x) in seen: continue
   q=[(r,x)]; seen.add((r,x)); comp=[]
   while q:
    y,z=q.pop();comp.append((y,z))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     yy,zz=y+dy,z+dx
     if 0<=yy<h and 0<=zz<w and a[yy][zz]==2 and (yy,zz) not in seen: seen.add((yy,zz));q.append((yy,zz))
   if any(y in rows or z in cols for y,z in comp):
    changed+=1
    for y,z in comp:out[y][z]=1
 for y in rows:
  for z in range(w):out[y][z]=1
 for z in cols:
  for y in range(h):out[y][z]=1
 print(mid,'axes rows',rows,'cols',cols,'recolored components',changed,'exact match',out==expected)
